const event = $json.body ?? $json;
const required = ['shootId','clientFirstName','clientEmail','shootDateTime','clientTimezone','roomUrl','invitationSentAt'];
if (required.some(key => !event[key])) return [{ json: { result: 'rejected_safely', reason: 'missing_required_field', emails: [] } }];
const shootAt = new Date(event.shootDateTime);
const invitationSentAt = new Date(event.invitationSentAt);
const acceptedAt = event.acceptedAt ? new Date(event.acceptedAt) : null;
if (Number.isNaN(shootAt.getTime()) || Number.isNaN(invitationSentAt.getTime()) || !event.clientEmail.includes('@')) return [{ json: { result: 'rejected_safely', reason: 'invalid_schedule_or_email', emails: [] } }];
const milestones = [
  ['shoot_room_invitation', invitationSentAt],
  ['preparation_guidance', acceptedAt ?? invitationSentAt],
  ['call_mira_reminder', acceptedAt ? new Date(acceptedAt.getTime() + 48 * 3600000) : invitationSentAt],
  ['shoot_day_reminder', new Date(shootAt.getTime() - 24 * 3600000)]
];
const processed = new Set(event.processedMilestones ?? []);
const completed = Boolean(event.preparationCompletedAt);
const valid = event.invitationValid !== false;
const cancelled = Boolean(event.shootCancelled);
const closeToShoot = shootAt.getTime() - invitationSentAt.getTime() < 24 * 3600000;
const emails = milestones.map(([milestone, rawAt]) => {
  const at = rawAt.getTime() > shootAt.getTime() ? shootAt : rawAt;
  let status = 'scheduled';
  let suppressionReason = null;
  if (processed.has(milestone)) status = 'sent';
  else if (completed) { status = 'suppressed'; suppressionReason = 'preparation_completed'; }
  else if (!valid) { status = 'suppressed'; suppressionReason = 'invitation_invalid'; }
  else if (cancelled) { status = 'cancelled'; suppressionReason = 'shoot_cancelled'; }
  else if (rawAt.getTime() > shootAt.getTime()) { status = 'suppressed'; suppressionReason = 'after_shoot'; }
  else if ((milestone === 'preparation_guidance' || milestone === 'call_mira_reminder') && !acceptedAt) { status = 'suppressed'; suppressionReason = 'awaiting_acceptance'; }
  else if (milestone === 'shoot_day_reminder' && closeToShoot) { status = 'suppressed'; suppressionReason = 'compressed_schedule'; }
  return { milestone, scheduledAt: at.toISOString(), status, suppressionReason, to: event.clientEmail, roomUrl: event.roomUrl, idempotencyKey: `mira:shoot:${event.shootId}:milestone:${milestone}` };
});
return [{ json: { result: 'prepared_not_sent', shootId: event.shootId, emails } }];
